-- Demo seed — jazz technicians and venue jobs. Replaces
-- backend/database/seeds/seed_data.py, which the raw/no-Docker flavor cannot run
-- (no Python after Phase 5). Generated from that seeder's own output, so the data is
-- identical; only the dates changed shape.
--
-- Dates are RELATIVE to the run date: the main demo day is always "today", the
-- follow-up day is tomorrow. The Python seeder used datetime.now() for the same reason.
--
-- Defined as api.seed_demo() so Start Demo can reset the day in-database, exactly as
-- FastAPI's /sim/start did by re-running the Python seeder. Applying this file also runs it.
--   psql -U fieldopt -d fieldopt -f db/seeds/01_seed.sql

create or replace function api.seed_demo()
returns void language plpgsql volatile
security definer set search_path = api, public as $seed$
begin
	truncate assignments, jobs, technicians restart identity cascade;

	-- ── Technicians (25) ─────────────────────────────────────────────────────────

	-- ── Jobs (55: 50 today, 5 tomorrow) ──────────────────────────────────────────
end;
$seed$;

grant execute on function api.seed_demo() to web_anon;

select api.seed_demo();
